    /// patch that turns the old list into the new one (a full value if they have little in
    /// common).
    /// - Note: A failure is logged and passed to `LoadOptions.onError`; the method does not throw.
    public func reset() {
        do {
            _ = try self.core.callSync(
                .objectMethod(handle: self.handle, methodId: UndraIds.Objects.BigList.reset),
                method: UndraIds.Objects.BigList.reset,
                args: []
            )
        } catch {
            self.core.report(error, operation: "BigList.reset")
        }
    }

    /// Changes the label of the row at `index` and bumps its version. One keyed `Update`.
    /// - Throws: ``ListError``, or ``UndraCallError`` if the call fails in the core or cannot reach it.
    public func updateAt(index: UInt32, label: String) throws {
        var w = UndraWriter()
        index.undraEncode(&w)
        label.undraEncode(&w)
        do {
            _ = try self.core.callSync(
                .objectMethod(handle: self.handle, methodId: UndraIds.Objects.BigList.updateAt),
                method: UndraIds.Objects.BigList.updateAt,
                args: w.finish()
            )
        } catch {
            throw UndraCallError.mapped(error, domain: ListError.self)
        }
    }

    public override func apply(signal: UInt32, op: ChangeOp, reader: inout UndraReader) {
        do {
            switch signal {
            case 0:
                switch op {
                case .fullValue:
                    let value = try [Item].undraDecode(&reader)
                    try reader.finish()
                    self.items = value
                case .keyedPatch:
                    let ops: [PatchOp<Item>] = try decodePatch(&reader)
                    try reader.finish()
                    try applyPatch(ops, to: &self.items)
                case .lazyListInvalidated:
                    break
                }
            case 1:
                switch op {
                case .fullValue:
                    let value = try UInt32.undraDecode(&reader)
                    try reader.finish()
                    self.count = value
                case .keyedPatch:
                    break
                case .lazyListInvalidated:
                    break
                }
            default:
                break
            }
        } catch is PatchError {
            // The mirror diverged from the core: re-observe to receive a full value.
            self.core.observe(self.handle, signal: signal, on: false)
            self.core.observe(self.handle, signal: signal, on: true)
        } catch {
            self.core.report(error, operation: "BigList.apply(signal: \(signal))")
        }
    }
}

/// A counter with a change tally and a computed parity.
@MainActor @Observable
public final class Counter: UndraStore, @unchecked Sendable {
    public private(set) var count: Int32 = 0
    public private(set) var changes: UInt32 = 0
    /// Computed by the core; read-only.
    public private(set) var parity: Parity = .even

    private init(adopting handle: UndraHandle, core: UndraCore) {
        super.init(core: core, handle: handle)
        core.observe(handle, signal: Observe.allSignals, on: true)
    }

    /// A counter at zero with no changes made.
    /// - Throws: ``UndraCallError`` if the call fails in the core or cannot reach it.
    public convenience init(ctx: UndraCore = .shared) throws {
        let handle: UndraHandle
