    public func decrement() {
        do {
            _ = try self.core.callSync(
                .objectMethod(handle: self.handle, methodId: UndraIds.Objects.Counter.decrement),
                method: UndraIds.Objects.Counter.decrement,
                args: []
            )
        } catch {
            self.core.report(error, operation: "Counter.decrement")
        }
    }

    /// Adds one.
    /// - Note: A failure is logged and passed to `LoadOptions.onError`; the method does not throw.
    public func increment() {
        do {
            _ = try self.core.callSync(
                .objectMethod(handle: self.handle, methodId: UndraIds.Objects.Counter.increment),
                method: UndraIds.Objects.Counter.increment,
                args: []
            )
        } catch {
            self.core.report(error, operation: "Counter.increment")
        }
    }

    /// Sets the count back to zero and forgets the changes, in one transaction.
    /// - Note: A failure is logged and passed to `LoadOptions.onError`; the method does not throw.
    public func reset() {
        do {
            _ = try self.core.callSync(
                .objectMethod(handle: self.handle, methodId: UndraIds.Objects.Counter.reset),
                method: UndraIds.Objects.Counter.reset,
                args: []
            )
        } catch {
            self.core.report(error, operation: "Counter.reset")
        }
    }

    public override func apply(signal: UInt32, op: ChangeOp, reader: inout UndraReader) {
        do {
            switch signal {
            case 0:
                switch op {
                case .fullValue:
                    let value = try Int32.undraDecode(&reader)
                    try reader.finish()
                    self.count = value
                case .keyedPatch:
                    break
                case .lazyListInvalidated:
                    break
                }
            case 1:
                switch op {
                case .fullValue:
                    let value = try UInt32.undraDecode(&reader)
                    try reader.finish()
                    self.changes = value
                case .keyedPatch:
                    break
                case .lazyListInvalidated:
                    break
                }
            case 2:
                switch op {
                case .fullValue:
                    let value = try Parity.undraDecode(&reader)
                    try reader.finish()
                    self.parity = value
                case .keyedPatch:
                    break
                case .lazyListInvalidated:
                    break
                }
            default:
                break
            }
        } catch is PatchError {
            // The mirror diverged from the core: re-observe to receive a full value.
            self.core.observe(self.handle, signal: signal, on: false)
            self.core.observe(self.handle, signal: signal, on: true)
        } catch {
            self.core.report(error, operation: "Counter.apply(signal: \(signal))")
        }
    }
}

/// A store that commits many transactions, for the coalesced-delivery scenarios and the
/// playground's stress screen.
@MainActor @Observable
public final class Stress: UndraStore, @unchecked Sendable {
    public private(set) var value: UInt64 = 0
    public private(set) var progress: UInt32 = 0
    public private(set) var generated: UInt64 = 0
    public private(set) var running: Bool = false

    private init(adopting handle: UndraHandle, core: UndraCore) {
        super.init(core: core, handle: handle, noCoalesce: [1])
        core.observe(handle, signal: Observe.allSignals, on: true)
    }

    /// A store with every signal at its start: zeros, and no generator running.
    /// - Throws: ``UndraCallError`` if the call fails in the core or cannot reach it.
    public convenience init(ctx: UndraCore = .shared) throws {
        let handle: UndraHandle
        do {
            handle = try ctx.construct(
                type: UndraIds.Objects.Stress.typeId,
                method: UndraIds.Objects.Stress.new,
                args: []
            )
        } catch {
            throw UndraCallError.mapped(error)
        }
        self.init(adopting: handle, core: ctx)
    }

    /// Commits `transactions` transactions now, each one write of the signal `mode` names: one
    /// change-set per transaction, the way data that arrives in the core on its own does.
    /// - Note: A failure is logged and passed to `LoadOptions.onError`; the method does not throw.
    public func burst(mode: StressMode, transactions: UInt32) {
        var w = UndraWriter()
        mode.undraEncode(&w)
        transactions.undraEncode(&w)
        do {
            _ = try self.core.callSync(
                .objectMethod(handle: self.handle, methodId: UndraIds.Objects.Stress.burst),
                method: UndraIds.Objects.Stress.burst,
                args: w.finish()
            )
        } catch {
            self.core.report(error, operation: "Stress.burst")
        }
    }

    /// Starts generating updates of the signal the mode names, at the given number a second,
    /// each its own transaction, until `stop`. Called while a generator runs, it retunes that
    /// generator (new mode, new rate) instead of starting a second one. Fails, starting
    /// nothing, when the rate is zero or above 1,000,000.
    /// - Throws: ``StressError``, or ``UndraCallError`` if the call fails in the core or cannot reach it.
    public func start(mode: StressMode, perSecond: UInt32) throws {
        var w = UndraWriter()
        mode.undraEncode(&w)
        perSecond.undraEncode(&w)
        do {
            _ = try self.core.callSync(
                .objectMethod(handle: self.handle, methodId: UndraIds.Objects.Stress.start),
                method: UndraIds.Objects.Stress.start,
                args: w.finish()
            )
        } catch {
            throw UndraCallError.mapped(error, domain: StressError.self)
        }
    }

    /// Stops the generator: no update is committed after this returns. `generated` keeps its
    /// count. Does nothing when no generator runs.
    /// - Note: A failure is logged and passed to `LoadOptions.onError`; the method does not throw.
    public func stop() {
        do {
            _ = try self.core.callSync(
                .objectMethod(handle: self.handle, methodId: UndraIds.Objects.Stress.stop),
                method: UndraIds.Objects.Stress.stop,
                args: []
            )
        } catch {
            self.core.report(error, operation: "Stress.stop")
        }
    }

    public override func apply(signal: UInt32, op: ChangeOp, reader: inout UndraReader) {
        do {
            switch signal {
            case 0:
                switch op {
                case .fullValue:
                    let value = try UInt64.undraDecode(&reader)
                    try reader.finish()
                    self.value = value
                case .keyedPatch:
                    break
                case .lazyListInvalidated:
                    break
                }
            case 1:
                switch op {
                case .fullValue:
                    let value = try UInt32.undraDecode(&reader)
                    try reader.finish()
                    self.progress = value
                case .keyedPatch:
                    break
                case .lazyListInvalidated:
                    break
                }
            case 2:
                switch op {
                case .fullValue:
                    let value = try UInt64.undraDecode(&reader)
                    try reader.finish()
                    self.generated = value
                case .keyedPatch:
                    break
                case .lazyListInvalidated:
                    break
                }
            case 3:
                switch op {
                case .fullValue:
                    let value = try Bool.undraDecode(&reader)
                    try reader.finish()
                    self.running = value
                case .keyedPatch:
                    break
                case .lazyListInvalidated:
                    break
                }
            default:
                break
            }
        } catch is PatchError {
            // The mirror diverged from the core: re-observe to receive a full value.
            self.core.observe(self.handle, signal: signal, on: false)
            self.core.observe(self.handle, signal: signal, on: true)
        } catch {
            self.core.report(error, operation: "Stress.apply(signal: \(signal))")
        }
    }
}

/// The to-do list: what the UI observes (`todos`, `filter`, `visible`, `remaining`) and calls.
@MainActor @Observable
public final class Todos: UndraStore, @unchecked Sendable {
    public private(set) var todos: [Todo] = []
    public private(set) var filter: Filter = .all
    /// Computed by the core; read-only.
    public private(set) var visible: [Todo] = []
    /// Computed by the core; read-only.
    public private(set) var remaining: UInt32 = 0

    private init(adopting handle: UndraHandle, core: UndraCore) {
        super.init(core: core, handle: handle)
        core.observe(handle, signal: Observe.allSignals, on: true)
    }

    /// An empty list showing every item.
    /// - Throws: ``UndraCallError`` if the call fails in the core or cannot reach it.
    public convenience init(ctx: UndraCore = .shared) throws {
        let handle: UndraHandle
        do {
            handle = try ctx.construct(
                type: UndraIds.Objects.Todos.typeId,
                method: UndraIds.Objects.Todos.new,
                args: []
            )
        } catch {
            throw UndraCallError.mapped(error)
        }
        self.init(adopting: handle, core: ctx)
    }

    /// Adds an item at the end of the list.
    /// - Throws: ``TodoError``, `CancellationError` if the task is cancelled, or ``UndraCallError``.
    public func add(title: String) async throws -> Todo {
        var w = UndraWriter()
        title.undraEncode(&w)
        do {
            let body = try await self.core.call(
                .objectMethod(handle: self.handle, methodId: UndraIds.Objects.Todos.add),
                method: UndraIds.Objects.Todos.add,
                args: w.finish()
            )
            return try Todo.undraDecoded(from: body)
